insert into public.recipes (id, owner_id, name, description, image_url, youtube_url, servings, prep_minutes, cook_minutes, meal_types, cuisine, calories_per_serving, protein_g_per_serving, carbs_g_per_serving, fat_g_per_serving, directions) values ('a6cda1de-2bcf-5daf-941e-36b44264592c', null, 'Moroccan Chicken Steak', 'Flame-grilled chicken breast drizzled with spicy sambal sauce, served with roasted veggies or rice.', null, 'https://www.youtube.com/results?search_query=moroccan+chicken+steak+recipe', 2, 15, 20, array['dinner', 'lunch']::text[], 'Continental', 344.32, 54.69, 2.8, 11.38, array['Marinate chicken breast with lemon juice, black pepper, paprika, and garlic for 15 mins.', 'Grill chicken breast on high heat with 1 tsp olive oil for 4–5 mins each side until charred and cooked through.', 'In a small pan, simmer chili paste, lemon juice, cream, and herbs to create the signature spicy Moroccan sauce.', 'Pour warm sauce over the grilled steaks and serve with roasted veggies or rice.']::text[]) on conflict (id) do nothing;
