insert into public.recipes (id, owner_id, name, description, image_url, youtube_url, servings, prep_minutes, cook_minutes, meal_types, cuisine, calories_per_serving, protein_g_per_serving, carbs_g_per_serving, fat_g_per_serving, directions) values ('92201286-398c-5229-9ca4-854e407b47b4', null, 'Black Pepper Chicken Steak', 'Pan-seared lean chicken breast with crushed black pepper-garlic reduction and roasted baby potatoes.', null, 'https://www.youtube.com/results?search_query=black+pepper+chicken+steak+recipe', 2, 10, 20, array['dinner']::text[], 'Continental', 433.44, 56.72, 23.34, 11.52, array['Pound chicken breast lightly and season with soy sauce, coarse black pepper, and garlic.', 'Sear in a hot skillet with olive oil for 5 minutes per side until golden brown.', 'Deglaze the skillet with broth, crushed peppercorns, and Worcestershire sauce for the pepper gravy.', 'Serve hot with roasted potatoes.']::text[]) on conflict (id) do nothing;
