insert into public.recipes (id, owner_id, name, description, image_url, youtube_url, servings, prep_minutes, cook_minutes, meal_types, cuisine, calories_per_serving, protein_g_per_serving, carbs_g_per_serving, fat_g_per_serving, directions) values ('307e77e8-1620-5265-9c81-fabe04d52d03', null, 'Dajaj bil Batata (Lemon-Garlic Chicken & Potatoes)', 'Chicken and baby potato wedges roasted together with dried oregano, garlic, and fresh lemon.', null, 'https://www.youtube.com/results?search_query=dajaj+bil+batata+recipe+lebanese', 4, 15, 40, array['dinner']::text[], 'Levant', 441.06, 40.93, 19.34, 21.47, array['Toss chicken pieces and potato wedges in a baking pan with garlic paste, lemon juice, olive oil, and oregano.', 'Season with salt and black pepper.', 'Roast in oven at 200°C (400°F) for 40 minutes until chicken is golden brown and potatoes are soft and crispy-edged.', 'Pour pan juices over the meat and serve.']::text[]) on conflict (id) do nothing;
